{
  "root_cause": "The checkboxes component only handles 'click' events for exclusive checkboxes, but keyboard activation (Space) triggers a 'change' event without a 'click', so the exclusive logic doesn't run and previously selected symptom checkboxes remain checked.",
  "repair_strategy": "Modify the component to also listen for 'change' events on checkboxes with data-checkbox-exclusive. When such a checkbox is checked, uncheck all other checkboxes in the same exclusive group and dispatch a change event to update form data.",
  "edits": [
    {
      "path": "./packages/nhsuk-frontend/src/nhsuk/components/checkboxes/checkboxes.js",
      "sha256": "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef",
      "before": "export function initCheckboxes() {
  const checkboxes = document.querySelectorAll('[data-module="nhsuk-checkboxes"]');
  checkboxes.forEach(container => {
    const inputs = container.querySelectorAll('input[type="checkbox"]');
    inputs.forEach(input => {
      input.addEventListener('click', handleClick);
    });
  });

  function handleClick(event) {
    const input = event.target;
    if (input.hasAttribute('data-checkbox-exclusive')) {
      const group = input.getAttribute('data-checkbox-exclusive-group');
      if (group && input.checked) {
        container.querySelectorAll(`input[type="checkbox"][data-checkbox-exclusive-group="${group}"]:not([data-checkbox-exclusive])`).forEach(cb => {
          cb.checked = false;
        });
      }
    }
  }
}",
      "after": "export function initCheckboxes() {
  const checkboxes = document.querySelectorAll('[data-module="nhsuk-checkboxes"]');
  checkboxes.forEach(container => {
    const inputs = container.querySelectorAll('input[type="checkbox"]');
    inputs.forEach(input => {
      input.addEventListener('click', handleClick);
      input.addEventListener('change', handleChange);
    });
  });

  function handleClick(event) {
    const input = event.target;
    if (input.hasAttribute('data-checkbox-exclusive')) {
      const group = input.getAttribute('data-checkbox-exclusive-group');
      if (group && input.checked) {
        container.querySelectorAll(`input[type="checkbox"][data-checkbox-exclusive-group="${group}"]:not([data-checkbox-exclusive])`).forEach(cb => {
          cb.checked = false;
          cb.dispatchEvent(new Event('change', { bubbles: true }));
        });
      }
    }
  }

  function handleChange(event) {
    const input = event.target;
    if (input.matches('input[type="checkbox"][data-checkbox-exclusive]')) {
      const group = input.getAttribute('data-checkbox-exclusive-group');
      if (group && input.checked) {
        document.querySelectorAll(`input[type="checkbox"][data-checkbox-exclusive-group="${group}"]:not([data-checkbox-exclusive])`).forEach(cb => {
          cb.checked = false;
          cb.dispatchEvent(new Event('change', { bubbles: true }));
        });
      }
    }
  }
}"
    }
  ],
  "expected_accessibility_effect": "Keyboard users can now select 'No, I do not have any of these symptoms' and have previously ticked symptom checkboxes automatically cleared, matching the expected behavior for exclusive checkbox groups and satisfying WCAG 2.1.1 (Keyboard) and 4.1.2 (Name, Role, Value).",
  "functional_risks": [
    "Duplicate change event handling if the component is later fixed, potentially causing double unchecking.",
    "The fix relies on the exclusive group attribute being present on all related checkboxes; if markup changes, the fix may not apply."
  ],
  "verification_requirements": [
    "Run the frozen journey: tab to cough, press Space, tab to fever, press Space, tab to none, press Space; verify form data symptoms[cough] and symptoms[fever] are empty.",
    "Test mouse click on 'none' checkbox still clears other checkboxes.",
    "Ensure contact checkboxes (different group) are unaffected."
  ]
}
